def apply_rewrite_rules(rules, urls):
    from urllib.parse import urlparse, urlunparse

    def parse_url(url):
        parsed = urlparse(url)
        # Hostname without port for path/host logic
        host = parsed.hostname or ''
        port = parsed.port
        if port is None:
            port = 443 if parsed.scheme == 'https' else (80 if parsed.scheme in ('http', '') else None)

        return {
            'scheme': parsed.scheme,
            'host': host,
            'port': port,
            'path': parsed.path or '/',
            'query': parsed.query,
        }

    def unparse_url(parsed):
        scheme = parsed.get('scheme', '')
        host = parsed.get('host', '')
        port = parsed.get('port')

        if port is not None:
            netloc = f"{host}:{port}"
        else:
            # Skip default ports (80/443) unless explicitly set
            if scheme in ('http', 'https'):
                netloc = host
            else:
                netloc = host

        path = parsed.get('path', '/')
        query = parsed.get('query', '')

        parts = [scheme, '', netloc, path, query]
        return urlunparse(parts) if scheme else ''

    results = []

    for url in urls:
        original_url = url
        parsed = parse_url(url)
        rewritten_url = None  # Default to None for block actions

        matched_rule_applies = False

        for rule in rules:
            match_type = rule.get('match_type')
            match_value = rule.get('match_value', '')
            action = rule.get('action', '')
            action_value = rule.get('action_value', '')

            if not parsed:
                break

            applies = False

            # Check matches based on rule type
            if match_type == 'path_prefix':
                path = parsed['path'] or '/'
                if path.startswith(match_value):
                    applies = True

            elif match_type == 'host':
                host = parsed['host'] or ''
                exact_match = host == match_value

                wildcard_match = False
                if match_value.startswith('*.'):
                    domain_suffix = match_value[2:]  # Remove "*. " prefix
                    if not domain_suffix:
                        continue

                    suffix_parts = domain_suffix.split('.')
                    try:
                        host_parts = host.split('.')
                    except AttributeError:
                        host_parts = []

                    if len(host_parts) > len(suffix_parts):
                        subdomain_check = '.'.join(host_parts[-len(suffix_parts):])
                        wildcard_match = (subdomain_check == domain_suffix) and (len(host_parts) > len(suffix_parts))

                if exact_match or wildcard_match:
                    applies = True

            elif match_type == 'query_param':
                query = parsed['query'] or ''
                if query:
                    # Parse query string to dict
                    query_params = {}
                    for pair in query.split('&'):
                        if '=' in pair:
                            key, val = pair.split('=', 1)
                            query_params[key] = val
                            if match_value == key:
                                applies = True

        # If no rule matched or block action applied
        if not matched_rule_applies:
            continue

        matched_rule_action = action
        matched_rule_action_value = action_value
        matched_type = match_type

        if action == 'block':
            results.append(None)
            break

        elif action == 'strip_prefix':
            path = parsed['path'] or '/'
            new_path = path[len(action_value):] if path.startswith(action_value) else path
            if not new_path:
                new_path = '/'
            parsed['path'] = new_path

        elif action == 'redirect_host':
            parsed['host'] = action_value

        elif action == 'add_query_param':
            query_str = parsed['query'] or ''
            if query_str:
                parsed['query'] = f"{query_str}&{action_value}"
            else:
                parsed['query'] = action_value

        # Reconstruct URL if applicable and not blocked
        if not matched_rule_action == 'block':
            reconstructed = unparse_url(parsed)
            results.append(reconstructed)
        else:
            results.append(None)

    return results
